BEGIN;
CREATE TEMP TABLE bs(n INTEGER PRIMARY KEY,title,url,kind,dt,scope,grade);
CREATE TEMP TABLE bt(id INTEGER PRIMARY KEY,name,province,city,address,category,status,typ,cap,water,level,src,missing);
UPDATE sites AS t SET name=coalesce(b.name,t.name),province=coalesce(b.province,t.province),city=coalesce(b.city,t.city),address=coalesce(b.address,t.address),category=coalesce(b.category,t.category),status=coalesce(b.status,t.status),record_type=coalesce(b.typ,t.record_type),capacity_summary=CASE WHEN b.cap IS NULL THEN t.capacity_summary ELSE coalesce(t.capacity_summary||'；','')||b.cap END,water_summary=CASE WHEN b.water IS NULL THEN t.water_summary ELSE coalesce(t.water_summary||'；','')||b.water END,water_level=coalesce(b.level,t.water_level),source_status='部分本轮复核',as_of='2026-11-27' FROM bt b WHERE t.site_id=printf('CN%04d',b.id) AND b.id<199;
CREATE TEMP TABLE bw(id,stream,stage,flow,unit,basis,poll,process,dest,resid,src,note);
CREATE TEMP TABLE bc(id,product,value,unit,basis,period,scope,src,note);
CREATE TEMP TABLE bm(id,point,metric,val,txt,unit,kind,stat,period,src,note);
CREATE TEMP TABLE bp(id,project,status,dt,cap,water,src);
INSERT OR IGNORE INTO site_sources SELECT printf('CN%04d',id),printf('W03S%02d',src) FROM (SELECT id,src FROM bt UNION SELECT id,src FROM bw UNION SELECT id,src FROM bc UNION SELECT id,src FROM bm UNION SELECT id,src FROM bp UNION SELECT 146,15 UNION SELECT 204,24 UNION SELECT 206,27 UNION SELECT 209,32);
UPDATE tasks AS t SET missing=b.missing,state='部分补证，待继续核实' FROM bt b WHERE t.site_id=printf('CN%04d',b.id) AND b.id<199;
UPDATE search_log SET source_id=NULL WHERE log_id='L0058';
DROP TABLE bs; DROP TABLE bt; DROP TABLE bw; DROP TABLE bc; DROP TABLE bm; DROP TABLE bp;
COMMIT;
